 var trade=op.GameObject.GetComponent<MiningTrade3D>()!;trade.Initialize();var ui=scene.GetComponentsSnapshot<MiningBusinessUi3D>().Single();var player=scene.FindGameObject(op.PlayerObjectId)!;var hp=player.GetComponent<HealthComponent>()!;var weapon=player.GetComponent<FpsGunLab3D>()!.SelectedWeapon!;
