 var enemy=scene.CreateGameObject("test disruptor");enemy.Transform.WorldPosition=mine.Transform.WorldPosition;enemy.AddComponent(new HealthComponent{MaxHealth=30,CurrentHealth=30});var disruptor=enemy.AddComponent(new MiningDisruptor3D{OperationObjectId=op.GameObject.Id});disruptor.Tick(.01f);Check(disruptor.WindupRemaining>0,"disruptor telegraphs before disabling");disruptor.Tick(1.1f);Check(mine.DisabledSeconds==3,"completed pulse disables nearby defence");
