 float scale=trade.AmmoPressUpgradePriceScale;trade.AmmoPressUpgradePriceScale=1;var priorPrices=Enumerable.Range(0,3).Select(trade.Cost).ToArray();trade.AmmoPressUpgradePriceScale=scale;for(int row=0;row<3;row++)Check(Math.Abs(trade.Cost(row)-priorPrices[row]*.8f)<=1,$"ammo press row {row+1} is discounted 20 percent");
